import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJ0NkIPM.js";var i=JSON.parse(`{"title":"Standard Modes / External Flight Mode failures","description":"","frontmatter":{},"headers":[],"relativePath":"en/qgc-user-guide/troubleshooting/standard_modes.md","filePath":"en/qgc-user-guide/troubleshooting/standard_modes.md"}`),a={name:`en/qgc-user-guide/troubleshooting/standard_modes.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="standard-modes-external-flight-mode-failures" tabindex="-1">Standard Modes / External Flight Mode failures <a class="header-anchor" href="#standard-modes-external-flight-mode-failures" aria-label="Permalink to “Standard Modes / External Flight Mode failures”">​</a></h1><p>Standard Modes is a <a href="https://mavlink.io/en/services/standard_modes.html" target="_blank" rel="noreferrer">MAVLink microservice</a> through which supporting firmware (including PX4 and ArduPilot) advertises its flight modes to <em>QGroundControl</em> during the initial connection, using the <code>AVAILABLE_MODES</code>, <code>AVAILABLE_MODES_MONITOR</code> and <code>CURRENT_MODE</code> messages. This includes externally-registered flight modes.</p><p>If an expected flight mode does not appear in the flight-mode selector (or the wrong mode name is shown), the information needed to debug the problem is <em>QGroundControl&#39;s</em> internal processing of these messages. A MAVLink traffic capture alone is not sufficient, since it does not show how <em>QGroundControl</em> processed the messages.</p><h2 id="capturing-a-standard-modes-log" tabindex="-1">Capturing a Standard Modes log <a class="header-anchor" href="#capturing-a-standard-modes-log" aria-label="Permalink to “Capturing a Standard Modes log”">​</a></h2><ol><li>Open <strong>Application Settings &gt; App Log Viewer</strong> and click <strong>Categories</strong>.</li><li>Enable the <code>Vehicle.StandardModes</code> logging category.</li><li>Reproduce the problem: connect the vehicle (with any external modes already registered) and wait for the connection sequence to complete.</li><li>Back in the App Log Viewer, click <strong>Save</strong> to save the application log to a file.</li></ol><p>The log shows each <code>AVAILABLE_MODES</code> mode as it is received (name, index, standard mode, custom mode, and flags), when mode retrieval completes, and any request failures or re-requests triggered by <code>AVAILABLE_MODES_MONITOR</code> changes.</p><h2 id="reporting-an-issue" tabindex="-1">Reporting an issue <a class="header-anchor" href="#reporting-an-issue" aria-label="Permalink to “Reporting an issue”">​</a></h2><p>When <a href="./../support/support.html">reporting an issue</a>, attach the saved <em>QGroundControl</em> app log captured as described above. A MAVLink capture may be attached in addition, but is not a substitute for the app log.</p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};